CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,is_admin BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id BIGSERIAL PRIMARY KEY,category_id BIGINT REFERENCES categories(id) ON DELETE SET NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',price NUMERIC(10,3) NOT NULL CHECK(price>=0),promo_price NUMERIC(10,3) CHECK(promo_price>=0),stock INT NOT NULL DEFAULT 0 CHECK(stock>=0),active BOOLEAN NOT NULL DEFAULT true,sales INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_cat_idx ON products(category_id);
CREATE INDEX IF NOT EXISTS products_list_idx ON products(active,created_at DESC);
CREATE TABLE IF NOT EXISTS product_images(id BIGSERIAL PRIMARY KEY,product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE,url TEXT NOT NULL,position INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS pimg_idx ON product_images(product_id,position);
CREATE TABLE IF NOT EXISTS orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,number VARCHAR(30) NOT NULL UNIQUE,full_name VARCHAR(160) NOT NULL,phone VARCHAR(30) NOT NULL,address TEXT NOT NULL,governorate VARCHAR(60) NOT NULL,city VARCHAR(100) NOT NULL,notes TEXT,total NUMERIC(10,3) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'nouvelle' CHECK(status IN('nouvelle','confirmee','en_preparation','expediee','livree','annulee')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_status_idx ON orders(status,created_at DESC);
CREATE TABLE IF NOT EXISTS order_items(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT REFERENCES products(id) ON DELETE SET NULL,name VARCHAR(190) NOT NULL,price NUMERIC(10,3) NOT NULL,qty INT NOT NULL CHECK(qty>0));
CREATE INDEX IF NOT EXISTS oi_idx ON order_items(order_id);
CREATE TABLE IF NOT EXISTS messages(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
